      "answer": "是英国现代小说之父笛福发表的世界上著名的冒险小说。主要讲述了一个叫作鲁滨逊的青年，不愿安享中产阶级的闲适生活，情愿外出冒险，寻求财富，结果船沉遇险而漂流到一个荒岛上。在荒岛生活了28年，凭借自己的智慧和双手，创造了一个美好的家园。鲁滨逊成了当时中小资产阶级心目中的英雄人物，是西方文学中“第一个理想化的新兴资产者形象”。 体现了资产阶级上升时期的创造精神和开拓精神，不过也有剥削掠夺的本性。",
