      "answer": "是法国启蒙运动时期最核心的成果。源于书商决定编写一部法国的百科全书，请文学家狄德罗和数学家达朗贝主持其事，内容包括自然科学和社会科学的各种知识，除此之外还有若干文学界知名人士撰写了文学方面的条目。《百科全书》成为新兴资产阶级与反动势力进行斗争的理论阵地，并以此把法国启蒙运动推向高潮。18世纪法国文学的主流体现了《百科全书》集中表现的启蒙运动精神。",
