      "answer": "是法国杰出的启蒙思想家狄德罗创作的对话体哲理小说。通过一个放荡无耻的人物“拉摩的侄儿”的言语，揭露了上流社会的腐朽，并就道德、艺术等等问题提出了一些独到的见解。被马克思称为“无与伦比的作品”，恩格斯称为“辩证法的杰作”。 拉摩的侄儿是法国由封建主义向资本主义过渡时期的典型产物，他性格中的矛盾正是当时社会矛盾的反映。",
