      "answer": "狂飙突进运动，它是德国新兴资产阶级全国性的文学运动，也是启蒙运动在德国的延续，发生在1765—1795年。含有摧枯拉朽之意，得名于德国剧作家克林格尔的同名悲剧《狂飙突进》。提倡个性解放、崇尚感情、礼赞天才人物和歌颂大自然。青年时代的歌德、席勒以及莱辛等是其主要代表作家。运用得最多的文学体裁是戏剧，如歌德的《铁手骑士葛兹·封·柏里欣根》。席勒的《阴谋与爱情》。小说方面影响最大的作品是歌德的《少年维特之烦恼》。",
