      "answer": "耶拿派是德国浪漫主义文学最早的一个流派。详尽地阐述了浪漫主义的文学主张。反对古典主义，要求创作的绝对自由，放纵主观幻想，追求神秘和奇异。理论奠基人是施莱格尔兄弟。代表性作品：诺瓦利斯的《夜的歌颂》。作者对人生采取否定的态度，歌颂死亡，把梦看成现实，把生活看成梦。",
