      "answer": "是德国启蒙思想家歌德创作的诗剧，取材于民间传说。上帝和魔鬼靡菲斯特在天上争论人的善恶，以下界的浮士德博士打赌。浮士德开始用一生追求五个阶段：知识的悲剧、爱情的悲剧、政治的悲剧、美的悲剧、事业的悲剧。浮士德的一生总结了人类发展的历史经验，尤其是资产阶级进步人士思想探索的历程。他具有一种“浮士德精神”，即：自强不息、不断进取、永不满足，积极向上的精神。",
