      "answer": "（1）启蒙运动与文艺复兴运动有着紧密的传承发展关系，继承并超越了人文主义理想。\n（2）工具：不再以宗教辅助文学与艺术复兴，而是力图以经验加理性思考而使知识系统能独立于宗教的影响，作为建立道德、美学以及思想体系的方式。\n（3）性质：启蒙运动是宣扬新的政治思想体系的运动，并非单纯是文学运动。它是文艺复兴运动反禁欲、反教会斗争的继续和发展，直接为1789年的法国大革命奠定了思想基础。\n（4）目标：启蒙思想家们进一步从理论上证明专制制度的不合理，从而提出一整套哲学理论、政治纲领和社会改革方案，要求建立一个以“理性”为基础的社会，即理想王国。\n（5）从历史背景上看，文艺复兴是资本主义萌芽，启蒙运动是资本主义发展；指导思想上前者是人文主义，后者是理性主义。主要领域上前者是文学、艺术，后者是政治、思想。",
      "classQuiz": true,
      "teacherFocus": true,
