      "answer": "（1）启蒙主义文学是启蒙运动的重要组成部分和强有力的战斗武器，它的产生一方面适应了欧洲资产阶级政治斗争的需要，另一方面也是新时代文学内容要求突破与封建主义相适应的古典主义的清规戒律的艺术表达。\n（2）有鲜明的政治倾向。启蒙作家在作品中猛烈抨击封建制度和教会，热情宣传自由、平等、博爱思想，描绘理性王国蓝图。\n（3）有深厚的哲理色彩。启蒙作家常常有意识地把自己的政治观点、哲学思想融入作品中，对生活进行分析、思索和评论，使作品带有寓意和象征性。法国启蒙主义小说家首创哲理小说。\n（4）有真实自然的创作风格。狄德罗提出文学创作“要真实、要自然”的主张，为近代资产阶级文学指出了新的方向。\n（5）有活泼多样的文学形式。如正剧（即莱辛的“市民悲剧”和狄德罗的“严肃喜剧”）、哲理小说、书信体小说、对话体小说、教育小说等。",
