      "answer": "第一，讴歌大自然\n（教材）卢梭在“返回自然”的思想指导下，讴歌大自然，把千姿百态的自然景色写进作品，大大开阔了人们的审美视野。\n第二，深入挖掘人性\n（教材）他改变了自画像的写法，不是在列举人物的德行和恶习，而是从根源去阐明行动和情感。他特别喜欢在孤独中对人生进行思索，总结自己的生活经验，挖掘自我。\n第三，充满激情\n（教材）卢梭的作品充满激情。他像一个辩证学家那样将自己的思想融进议论之中。\n第四，善于以定义或警句表达情感\n（教材）卢梭具有演说家的风格，他善于以定义的方式有力地表达自己的思想，如：“因此我将合法施行行政权称为政府。”或者以警句来表达，如：“对老人的研究在于学会死。”\n（教材）第五，文笔细腻、朴实清新富有诗意\n卢梭的描绘朴实清新，如《忏悔录》中关于采摘樱桃和《一个孤独散步者的遐想》中在布洛涅树林里遇到小姑娘的故事。这种文笔清新又富有诗意。",
