      "answer": "（1）维特代表启蒙运动德国的进步青年分子，体现启蒙时代精神。\n他有理想、有才能、渴望自由又力图有所作为。但现实的鄙陋，贵族的偏见，官府的腐败，市民的平庸，都使他不能容忍。他感到孤独，愁闷，但又无能为力，只得从大自然、天真的儿童和纯朴的农民身上找到一点宽慰。（事业失意）\n他从绿蒂身上看到了一种质朴纯真的品质，便寄以全部热情。但绿蒂也跳不出平庸的生活圈子，这使维特完全陷于绝望。（爱情无望）\n维特自杀是他为社会所不容的结果，是他既憎恶社会又找不到出路的必然归宿，同时也是他对那个令人窒息的社会的孤独而消极的抗议。（社会时代不容）\n维特爱情上的失败导致了内心无法解脱的矛盾和冲突以及他伤感、厌世的情绪。\n（2）内在原因之一是维特爱情上的失败导致了内心无法解脱的矛盾和冲突以及他伤感、厌世的情绪。三次打击分别是阿尔伯特从外地返回，梦想回到现实；阿尔伯特与绿蒂结婚；绿蒂的决绝。内在原因之二是他多愁善感的性格和好走极端的德意志民族思维方式。外在原因是封建专制制度的束缚。维特曾经想通过事业上的发展来摆脱爱情对他造成的心灵创伤。但是当时德国社会十分鄙陋，那些拘泥刻板的人，因循守旧对标新立异的维特很是反感，周围的人全都精神匮乏，空虚无聊，虚伪奸诈，社会上等级观念根深蒂固。如果有一个适合维特发展的社会环境，他完全能干出一番事业，从而摆脱对绿蒂的苦恋。但是德国鄙陋的社会的封建制度把他推向了毁灭的悬崖。\n（3）维特形象蕴含了18世纪下半叶德国的社会阶级内容和时代思潮，维特身上带着德国资产阶级软弱无力的印记，使他成了反叛的受难者。维特的悲剧是那个时代的产物，对于一个像维特一样的人，在这个虚伪黑暗的社会是根本无法融合的，格格不入的。\n通过维特的悲剧，小说揭露和批判了当时德国社会许多不合理的现象，表达了觉醒的德意志青年一代的革命情绪。",
