      "answer": "（1）\n（精神内涵） “浮士德精神”，即：自强不息、不断进取、永不满足，积极向上的精神；\n（主要思想价值）\n1．宣传挣脱中世纪的愚昧状态，克服人类内在和外在的矛盾，创造资产阶级理想王国的启蒙思想。\n2．通过浮士德的人生经历，宣传自强不息的进取精神，作者对人类的坚定信念：在前进的道路上，人们会遇到这样那样的阻碍，但最终会找到人生的真理，为实现崇高的目标而奋斗；\n3．表达了一种现代意义，即人始终处于与外界的冲突中，失败和灾难无法避免，但主人公以自身的行动决定自己的本质，从而奠定了现代人格的基础。\n（2）1.走出书斋，投身社会。——知识的悲剧，对中世纪思想体系的否定。\n年过半百的学者浮士德在狭窄的书斋里长期研究中世纪的“四大学科”：哲学、医学、法律和神学，脱离了现实生活，为烦琐、僵死的知识所困，苦闷到企图自杀。靡非斯特与之订立契约，甘愿做浮士德的仆人，带他到天地间寻求各种满足，解除他的苦闷。\n2.追求个人幸福——爱情的悲剧，对文艺复兴资产阶级放纵情欲的反思，对德国市民阶层封建意识的批判。\n浮士德离开了书斋。他喝下了魔汤，恢复了青春，化身贵族，爱上了平民少女格蕾琴。深陷爱中的格蕾琴却因此家破人亡，虔诚于宗教的她在狱中等待上帝的裁判。浮士德经历了瓦尔普吉斯之夜群魔会，赶来解救格蕾琴，却遭其拒绝，内心感到了极大的痛苦。\n3.为宫廷服务阶段——政治的悲剧，对“开明君主制”改良社会的否定。\n浮士德继续得到靡菲斯特的帮助，从个人的小世界投身社会的大世界：开始他接触政治生活，希求功名，向皇帝倡议大量发行钞票，解救了财政危机，却被昏庸的皇帝视作浅陋的魔法师。\n4.追求古典艺术——美的悲剧，对古典主义、浪漫主义、用艺术改造社会的理想的反思。\n他穿越时空，追求古希腊的美女海伦，并与海伦结婚生子，儿子欧福里翁无限制的追求高飞，却坠地身亡，海伦也悲痛离去。\n5.在改造自然中找到真理——事业的悲剧，19世纪空想社会主义、科学革命的反映。\n回到现实后，浮士德帮助国王平息了叛乱，得到一块赏地，他决定筑堤拦海，改造自然，却间接害死了无辜百姓。在这过程中，他双目失明了，听到为他掘墓的声音，却以为是大堤将成的信号，激动的他由衷盼望时间为之停留，随即颓然倒地。\n按照赌约，他的灵魂将归魔鬼所有。但天使及时到来拯救了他，他进入天国见到了圣母与格蕾琴。\n（3）首先，浮士德是一个不朽的艺术典型。他是上升时期的资产阶级形象，他不断地追求知识和真理，追求美好的事物，追求崇高的理想。他具有一种“浮士德精神”，即：自强不息、不断进取、永不满足，积极向上的精神；\n但同时他又有贪图享乐、安于现状、平庸卑俗的一面，这就构成了其内部的矛盾。浮士德性格是一个善恶并存的矛盾统一体。这种矛盾性正是资产阶级的两重性的表现。他的一生总结了人类发展的历史经验，尤其是资产阶级进步人士思想探索的历程。\n而靡非斯特代表恶、虚无的“否定精神”，随时把浮士德引向堕落；但是，靡非斯特的“恶”从反面推动了浮士德的进步，他一再引诱浮士德，实际使浮士德从错误中摸索到正途，不断向真理前进；靡非斯特的形象体现了歌德的辩证法精神。\n浮士德和靡菲斯特如影随形，相辅相成，表明人和事物的发展过程中“善”和“恶”、肯定和否定、前进与停滞是不可分割的，它们既相互斗争又相互依存。首先，浮士德在人生探索路上五个阶段的追求，始终是以靡菲斯特这个“恶”的化身作为推动力的。其次，浮士德也不是绝对的“善”，靡菲斯特也并不是绝对的“恶”，而是浮士德在行“善”中有“恶”，靡菲斯特行“恶”中含有“善”。“善”与“恶”在他们身上彼此渗透，相互影响。\n因此，浮士德和靡菲斯特是一个人的“善”与“恶”的两方面，是一个辩证的统一体。",
